python3 -c "
from openpyxl import load_workbook
wb = load_workbook('gdp.xlsx')
task = wb['Task']

# Step 1: Populate data using VLOOKUP & MATCH with ;
for r in range(12, 18):
    for col_let in ['H', 'I', 'J', 'K', 'L']:
        task[f'{col_let}{r}'] = f'=VLOOKUP($D{r}; Data!$B$21:$M$42; MATCH({col_let}$9; Data!$B$4:$M$4; 0); 0)'

for r in range(19, 25):
    for col_let in ['H', 'I', 'J', 'K', 'L']:
        task[f'{col_let}{r}'] = f'=VLOOKUP($D{r}; Data!$B$21:$M$42; MATCH({col_let}$9; Data!$B$4:$M$4; 0); 0)'

for r in range(26, 32):
    for col_let in ['H', 'I', 'J', 'K', 'L']:
        task[f'{col_let}{r}'] = f'=VLOOKUP($D{r}; Data!$B$21:$M$42; MATCH({col_let}$9; Data!$B$4:$M$4; 0); 0)'

# Step 2: Calculate net exports % of GDP H35:L40
for r in range(35, 41):
    exp_r = r - 35 + 12
    imp_r = r - 35 + 19
    gdp_r = r - 35 + 26
    for col_let in ['H', 'I', 'J', 'K', 'L']:
        task[f'{col_let}{r}'] = f'=({col_let}{exp_r}-{col_let}{imp_r})/{col_let}{gdp_r}*100'

# Statistics H42:L47
for col_let in ['H', 'I', 'J', 'K', 'L']:
    task[f'{col_let}42'] = f'=MIN({col_let}35:{col_let}40)'
    task[f'{col_let}43'] = f'=MAX({col_let}35:{col_let}40)'
    task[f'{col_let}44'] = f'=MEDIAN({col_let}35:{col_let}40)'
    task[f'{col_let}45'] = f'=AVERAGE({col_let}35:{col_let}40)'
    task[f'{col_let}46'] = f'=PERCENTILE({col_let}35:{col_let}40; 0.25)'
    task[f'{col_let}47'] = f'=PERCENTILE({col_let}35:{col_let}40; 0.75)'

# Step 3: Weighted mean H50:L50
for col_let in ['H', 'I', 'J', 'K', 'L']:
    task[f'{col_let}50'] = f'=SUMPRODUCT({col_let}35:{col_let}40; {col_let}26:{col_let}31) / SUM({col_let}26:{col_let}31)'

wb.save('gdp.xlsx')
" && python3 .gemini/skills/xlsx/recalc.py gdp.xlsx
